     1	package com.pousada.strategy;
     2	
     3	import com.pousada.domain.Reservation;
     4	import com.pousada.domain.ReservationStatus;
     5	import com.pousada.domain.Room;
     6	
     7	import java.time.LocalDate;
     8	import java.time.format.DateTimeFormatter;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	
    12	public class OccupancyReportStrategy implements ReportStrategy {
    13	    @Override
    14	    public String generate(List<Reservation> reservations, List<Room> rooms, Object parameter) {
    15	        LocalDate date = (LocalDate) parameter;
    16	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    17	
    18	        StringBuilder csv = new StringBuilder();
    19	        csv.append("Pousada Maré Alta,occupancy,").append(date.format(dateFormatter)).append("\n");
    20	        csv.append("room,type,reservation,check_in,check_out\n");
    21	
    22	        List<Reservation> occupiedReservations = reservations.stream()
    23	                .filter(r -> isPaid(r.getStatus()))
    24	                .filter(r -> occupiesNight(r, date))
    25	                .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
    26	                .toList();
    27	
    28	        for (Reservation reservation : occupiedReservations) {
    29	            Room room = rooms.stream()
    30	                    .filter(r -> r.getNumber() == reservation.getRoomNumber())
    31	                    .findFirst()
    32	                    .orElseThrow();
    33	
    34	            csv.append(reservation.getRoomNumber()).append(",");
    35	            csv.append(room.getType()).append(",");
    36	            csv.append(reservation.getId()).append(",");
    37	            csv.append(reservation.getCheckIn().format(dateFormatter)).append(",");
    38	            csv.append(reservation.getCheckOut().format(dateFormatter)).append("\n");
    39	        }
    40	
    41	        csv.append("total,").append(occupiedReservations.size()).append("/").append(rooms.size());
    42	
    43	        return csv.toString();
    44	    }
    45	
    46	    @Override
    47	    public String getReportName() {
    48	        return "occupancy";
    49	    }
    50	
    51	    private boolean isPaid(ReservationStatus status) {
    52	        return status == ReservationStatus.CONFIRMED ||
    53	               status == ReservationStatus.CHECKED_IN ||
    54	               status == ReservationStatus.CHECKED_OUT;
    55	    }
    56	
    57	    private boolean occupiesNight(Reservation reservation, LocalDate night) {
    58	        return !reservation.getCheckIn().isAfter(night) &&
    59	               reservation.getCheckOut().isAfter(night);
    60	    }
    61	}
