     1	package com.pousada.strategy;
     2	
     3	import com.pousada.domain.RatePlan;
     4	import com.pousada.domain.Reservation;
     5	import com.pousada.domain.Room;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.YearMonth;
     9	import java.time.format.DateTimeFormatter;
    10	import java.util.HashMap;
    11	import java.util.List;
    12	import java.util.Map;
    13	
    14	public class RatePlansReportStrategy implements ReportStrategy {
    15	    @Override
    16	    public String generate(List<Reservation> reservations, List<Room> rooms, Object parameter) {
    17	        YearMonth month = (YearMonth) parameter;
    18	        DateTimeFormatter monthFormatter = DateTimeFormatter.ofPattern("yyyy-MM");
    19	
    20	        StringBuilder csv = new StringBuilder();
    21	        csv.append("Pousada Maré Alta,rate-plans,").append(month.format(monthFormatter)).append("\n");
    22	        csv.append("rate_plan,reservations,amount\n");
    23	
    24	        Map<RatePlan, PlanStats> stats = new HashMap<>();
    25	        stats.put(RatePlan.STANDARD, new PlanStats());
    26	        stats.put(RatePlan.NON_REFUNDABLE, new PlanStats());
    27	
    28	        reservations.stream()
    29	                .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
    30	                .forEach(r -> {
    31	                    BigDecimal netRevenue = getNetRevenue(r);
    32	                    if (netRevenue.compareTo(BigDecimal.ZERO) > 0) {
    33	                        PlanStats planStats = stats.get(r.getRatePlan());
    34	                        planStats.count++;
    35	                        planStats.amount = planStats.amount.add(netRevenue);
    36	                    }
    37	                });
    38	
    39	        int totalCount = 0;
    40	        BigDecimal totalAmount = BigDecimal.ZERO;
    41	
    42	        for (RatePlan plan : RatePlan.values()) {
    43	            PlanStats planStats = stats.get(plan);
    44	            csv.append(plan).append(",");
    45	            csv.append(planStats.count).append(",");
    46	            csv.append(formatCsvNumber(planStats.amount)).append("\n");
    47	
    48	            totalCount += planStats.count;
    49	            totalAmount = totalAmount.add(planStats.amount);
    50	        }
    51	
    52	        csv.append("total,").append(totalCount).append(",").append(formatCsvNumber(totalAmount));
    53	
    54	        return csv.toString();
    55	    }
    56	
    57	    @Override
    58	    public String getReportName() {
    59	        return "rate-plans";
    60	    }
    61	
    62	    private BigDecimal getNetRevenue(Reservation reservation) {
    63	        BigDecimal paid = reservation.getAmountPaid();
    64	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
    65	        return paid.subtract(refunded);
    66	    }
    67	
    68	    private String formatCsvNumber(BigDecimal number) {
    69	        return number.setScale(2).toString().replace(",", "");
    70	    }
    71	
    72	    private static class PlanStats {
    73	        int count = 0;
    74	        BigDecimal amount = BigDecimal.ZERO;
    75	    }
    76	}
