     9	import java.util.Comparator;
    10	import java.util.List;
    11	
    12	public class RevenueReportStrategy implements ReportStrategy {
    13	    @Override
    14	    public String generate(List<Reservation> reservations, List<Room> rooms, Object parameter) {
    15	        YearMonth month = (YearMonth) parameter;
    16	        DateTimeFormatter monthFormatter = DateTimeFormatter.ofPattern("yyyy-MM");
    17	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    18	
    19	        StringBuilder csv = new StringBuilder();
    20	        csv.append("Pousada Maré Alta,revenue,").append(month.format(monthFormatter)).append("\n");
    21	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    22	
    23	        BigDecimal totalAmount = BigDecimal.ZERO;
    24	
    25	        List<Reservation> monthReservations = reservations.stream()
    26	                .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
    27	                .filter(r -> getNetRevenue(r, rooms).compareTo(BigDecimal.ZERO) > 0)
    28	                .sorted(Comparator.comparing(Reservation::getCheckIn)
    29	                        .thenComparingLong(Reservation::getId))
    30	                .toList();
    31	
    32	        for (Reservation reservation : monthReservations) {
    33	            BigDecimal amount = getNetRevenue(reservation, rooms);
    34	            totalAmount = totalAmount.add(amount);
    35	
    36	            csv.append(reservation.getId()).append(",");
    37	            csv.append(reservation.getRoomNumber()).append(",");
    38	            csv.append(reservation.getCheckIn().format(dateFormatter)).append(",");
    39	            csv.append(reservation.getCheckOut().format(dateFormatter)).append(",");
    40	            csv.append(reservation.getStatus()).append(",");
    41	            csv.append(formatCsvNumber(amount)).append("\n");
    42	        }
    43	
    44	        csv.append("total,").append(formatCsvNumber(totalAmount));
    45	
    46	        return csv.toString();
    47	    }
    48	
    49	    @Override
    50	    public String getReportName() {
    51	        return "revenue";
    52	    }
    53	
    54	    private BigDecimal getNetRevenue(Reservation reservation, List<Room> rooms) {
    55	        BigDecimal paid = reservation.getAmountPaid();
    56	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
    57	        return paid.subtract(refunded);
    58	    }
    59	
    60	    private String formatCsvNumber(BigDecimal number) {
    61	        return number.setScale(2).toString().replace(",", "");
    62	    }
    63	}
