     1	package com.pousada.strategy;
     2	
     3	import com.pousada.domain.Reservation;
     4	import com.pousada.domain.ReservationStatus;
     5	import com.pousada.domain.Room;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.YearMonth;
     9	import java.time.format.DateTimeFormatter;
    10	import java.util.Comparator;
    11	import java.util.List;
    12	
    13	public class TourismTaxReportStrategy implements ReportStrategy {
    14	    private static final BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
    15	
    16	    @Override
    17	    public String generate(List<Reservation> reservations, List<Room> rooms, Object parameter) {
    18	        YearMonth month = (YearMonth) parameter;
    19	        DateTimeFormatter monthFormatter = DateTimeFormatter.ofPattern("yyyy-MM");
    20	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    21	
    22	        StringBuilder csv = new StringBuilder();
    23	        csv.append("Pousada Maré Alta,tourism-tax,").append(month.format(monthFormatter)).append("\n");
    24	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
    25	
    26	        BigDecimal totalTax = BigDecimal.ZERO;
    27	
    28	        List<Reservation> paidReservations = reservations.stream()
    29	                .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
    30	                .filter(r -> isPaid(r.getStatus()))
    31	                .sorted(Comparator.comparing(Reservation::getCheckIn)
    32	                        .thenComparingLong(Reservation::getId))
    33	                .toList();
    34	
    35	        for (Reservation reservation : paidReservations) {
    36	            BigDecimal tax = calculateTax(reservation);
    37	            totalTax = totalTax.add(tax);
    38	
    39	            csv.append(reservation.getId()).append(",");
    40	            csv.append(reservation.getRoomNumber()).append(",");
    41	            csv.append(reservation.getCheckIn().format(dateFormatter)).append(",");
    42	            csv.append(reservation.getCheckOut().format(dateFormatter)).append(",");
    43	            csv.append(reservation.getGuests()).append(",");
    44	            csv.append(reservation.getNights()).append(",");
    45	            csv.append(formatCsvNumber(tax)).append("\n");
    46	        }
    47	
    48	        csv.append("total,").append(formatCsvNumber(totalTax));
    49	
    50	        return csv.toString();
    51	    }
    52	
    53	    @Override
    54	    public String getReportName() {
    55	        return "tourism-tax";
    56	    }
    57	
    58	    private boolean isPaid(ReservationStatus status) {
    59	        return status == ReservationStatus.CONFIRMED ||
    60	               status == ReservationStatus.CHECKED_IN ||
    61	               status == ReservationStatus.CHECKED_OUT;
    62	    }
    63	
    64	    private BigDecimal calculateTax(Reservation reservation) {
    65	        int guestNights = reservation.getGuests() * reservation.getNights();
    66	        return TAX_PER_GUEST_PER_NIGHT.multiply(new BigDecimal(guestNights));
    67	    }
    68	
    69	    private String formatCsvNumber(BigDecimal number) {
    70	        return number.setScale(2).toString().replace(",", "");
    71	    }
    72	}
