    49	    @Override
    50	    public String getReportName() {
    51	        return "revenue";
    52	    }
    53	
    54	    private BigDecimal getNetRevenue(Reservation reservation, List<Room> rooms) {
    55	        BigDecimal paid = reservation.getAmountPaid();
    56	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
    57	        return paid.subtract(refunded);
    58	    }
