    58	    private boolean isPaid(ReservationStatus status) {
    59	        return status == ReservationStatus.CONFIRMED ||
    60	               status == ReservationStatus.CHECKED_IN ||
    61	               status == ReservationStatus.CHECKED_OUT;
    62	    }
    63	
    64	    private BigDecimal calculateTax(Reservation reservation) {
    65	        int guestNights = reservation.getGuests() * reservation.getNights();
    66	        return TAX_PER_GUEST_PER_NIGHT.multiply(new BigDecimal(guestNights));
