 69	
 70	        app.exception(IllegalArgumentException.class, (e, ctx) -> {
 71	            String errorCode = e.getMessage();
 72	
 73	            switch (errorCode) {
 74	                case "ROOM_NOT_FOUND":
 75	                case "RESERVATION_NOT_FOUND":
 76	                    ctx.status(404).json(new ErrorResponse(errorCode, getErrorMessage(errorCode)));
 77	                    break;
 78	                case "ROOM_UNAVAILABLE":
 79	                case "OPERATION_NOT_ALLOWED":
 80	                    ctx.status(409).json(new ErrorResponse(errorCode, getErrorMessage(errorCode)));
 81	                    break;
 82	                case "CAPACITY_EXCEEDED":
 83	                    ctx.status(422).json(new ErrorResponse(errorCode, getErrorMessage(errorCode)));
 84	                    break;
 85	                case "INVALID_REQUEST":
 86	                default:
 87	                    ctx.status(400).json(new ErrorResponse(errorCode, getErrorMessage(errorCode)));
 88	                    break;
 89	            }
 90	        });
 91	
