200	
201	    public Reservation(long id, int roomNumber, String guestName, String guestEmail,
202	                      String guestCpf, LocalDate checkIn, LocalDate checkOut,
203	                      int guests, RatePlan ratePlan) {
204	        this.id = id;
205	        this.roomNumber = roomNumber;
206	        this.guestName = guestName;
207	        this.guestEmail = guestEmail;
208	        this.guestCpf = guestCpf;
209	        this.checkIn = checkIn;
210	        this.checkOut = checkOut;
211	        this.guests = guests;
212	        this.ratePlan = ratePlan;
213	        this.ratePlanStrategy = createRatePlanStrategy(ratePlan);
214	        this.state = new PendingState();
215	        this.amountPaid = BigDecimal.ZERO;
216	        this.refund = null;
217	    }
218	
219	    private RatePlanStrategy createRatePlanStrategy(RatePlan plan) {
220	        return switch (plan) {
221	            case STANDARD -> new StandardRatePlan();
222	            case NON_REFUNDABLE -> new NonRefundableRatePlan();
223	        };
224	    }
