230	    public BigDecimal calculateNightlyRate(LocalDate date, BigDecimal baseRate) {
231	        if (isHighSeason(date)) {
232	            BigDecimal highSeasonRate = baseRate.multiply(new BigDecimal("1.20"));
233	            return highSeasonRate.setScale(2, RoundingMode.HALF_EVEN);
234	        }
235	        return baseRate;
236	    }
237	
238	    private boolean isHighSeason(LocalDate date) {
239	        int month = date.getMonthValue();
240	        int day = date.getDayOfMonth();
241	
242	        if (month == 7) {
243	            return true;
244	        }
245	
246	        if (month == 12 && day >= 15) {
247	            return true;
248	        }
249	
250	        if (month == 1 || month == 2) {
251	            return true;
252	        }
253	
254	        return false;
255	    }
