257	    public BigDecimal calculateSubtotal(BigDecimal baseRate) {
258	        BigDecimal subtotal = BigDecimal.ZERO;
259	        LocalDate current = checkIn;
260	
261	        while (current.isBefore(checkOut)) {
262	            BigDecimal nightlyRate = calculateNightlyRate(current, baseRate);
263	            subtotal = subtotal.add(nightlyRate);
264	            current = current.plusDays(1);
265	        }
266	
267	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
268	    }
