153	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
154	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
155	                                        int guests, RatePlan ratePlan) {
156	
157	        Room room = roomRepository.findByNumber(roomNumber)
158	                .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
159	
160	        if (guests < 1) {
161	            throw new IllegalArgumentException("INVALID_REQUEST");
162	        }
163	
164	        if (guests > room.getCapacity()) {
165	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
166	        }
167	
168	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
169	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
170	        }
171	
172	        long id = reservationRepository.generateId();
173	        Reservation reservation = new Reservation(
174	                id, roomNumber, guestName, guestEmail, guestCpf,
175	                checkIn, checkOut, guests, ratePlan
176	        );
177	
178	        return reservationRepository.save(reservation);
179	    }
