187	        Reservation reservation = getReservation(id);
188	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
189	
190	        BigDecimal subtotal = reservation.calculateSubtotal(room.getNightlyRate());
191	        BigDecimal discount = reservation.calculateDiscount(subtotal);
192	        BigDecimal total = reservation.calculateTotal(subtotal, discount);
193	
194	        reservation.confirm(total);
195	
196	        String document = generateDocument(reservation, room, subtotal, discount, total);
197	        sendConfirmationEmail(reservation, document);
198	
199	        return reservation;
200	    }
