468	public class ReservationRepository {
469	    private final List<Reservation> reservations;
470	    private final AtomicLong idGenerator;
471	
472	    public ReservationRepository() {
473	        this.reservations = new ArrayList<>();
474	        this.idGenerator = new AtomicLong(1);
475	    }
476	
477	    public Reservation save(Reservation reservation) {
478	        reservations.add(reservation);
479	        return reservation;
480	    }
481	
482	    public Optional<Reservation> findById(long id) {
483	        return reservations.stream()
484	                .filter(r -> r.getId() == id)
485	                .findFirst();
486	    }
487	
488	    public List<Reservation> findAll() {
489	        return new ArrayList<>(reservations);
490	    }
491	
492	    public long generateId() {
493	        return idGenerator.getAndIncrement();
494	    }
495	
496	    public boolean hasConflict(int roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
497	        return reservations.stream()
498	                .filter(r -> r.getRoomNumber() == roomNumber)
499	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
500	                .filter(r -> excludeId == null || r.getId() != excludeId)
501	                .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
502	    }
503	
504	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
505	        return start1.isBefore(end2) && start2.isBefore(end1);
506	    }
