    25	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    26	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    27	                                        int guests, RatePlan ratePlan) {
    28	
    29	        Room room = roomRepository.findByNumber(roomNumber)
    30	                .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
    31	
    32	        if (guests < 1) {
    33	            throw new IllegalArgumentException("INVALID_REQUEST");
