   100	        doc.append("Quarto: ").append(reservation.getRoomNumber())
   101	           .append(" (").append(room.getType()).append(")\n");
   102	        doc.append("Entrada: ").append(reservation.getCheckIn().format(dateFormatter))
   103	           .append(" | Saída: ").append(reservation.getCheckOut().format(dateFormatter))
   104	           .append(" | ").append(reservation.getNights())
   105	           .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
   106	        doc.append("Diárias: ").append(formatMoney(subtotal)).append("\n");
   107	
