     9	import java.util.Optional;
    10	import java.util.concurrent.atomic.AtomicLong;
    11	
    12	public class ReservationRepository {
    13	    private final List<Reservation> reservations;
    14	    private final AtomicLong idGenerator;
    15	
    16	    public ReservationRepository() {
    17	        this.reservations = new ArrayList<>();
    18	        this.idGenerator = new AtomicLong(1);
    19	    }
    20	
    21	    public Reservation save(Reservation reservation) {
    22	        reservations.add(reservation);
    23	        return reservation;
    24	    }
    25	
    26	    public Optional<Reservation> findById(long id) {
    27	        return reservations.stream()
    28	                .filter(r -> r.getId() == id)
    29	                .findFirst();
    30	    }
    31	
    32	    public List<Reservation> findAll() {
    33	        return new ArrayList<>(reservations);
    34	    }
    35	
    36	    public long generateId() {
    37	        return idGenerator.getAndIncrement();
    38	    }
    39	
    40	    public boolean hasConflict(int roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
    41	        return reservations.stream()
    42	                .filter(r -> r.getRoomNumber() == roomNumber)
    43	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
    44	                .filter(r -> excludeId == null || r.getId() != excludeId)
    45	                .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
    46	    }
    47	
    48	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
    49	        return start1.isBefore(end2) && start2.isBefore(end1);
    50	    }
    51	}
